#!/usr/bin/env python3
"""Persist the human-reviewed, purposive sample; this is not automatic entailment scoring."""
import json,pathlib
out=pathlib.Path(__file__).resolve().parent
root=out.parent/'r1-snapshot'
structure=json.loads((out/'structural_results.json').read_text())
idx={}
for prefix in ['MAT','ANC','IND','LBR']:
    for kind in ['claims','sources','cases','graph']:
        obj=json.loads((root/'contributions'/prefix/(kind+'.json')).read_text())
        for row in (obj['edges']+obj['nodes'] if kind=='graph' else obj):idx[row['id']]=row
reviews={
'ANC-E06':dict(selection='Reported coerced workforce; first edge in a funding→workforce→service path.',verdict='supported_with_limits',source_reviewed=['ANC-S05'],assessment='Frontinus §§116–117 names enslaved gangs and specialist duties; high confidence fits the reported assignment, not realised reliability. ANC-K09 remains medium/underdetermined. ANC-C03 actors.ability_to_refuse does not turn expenses into free labour. Alternatives include contractors, correctly avoiding necessity.'),
'ANC-E07':dict(selection='Second edge of same within-episode path; finance and coercion distinction.',verdict='supported_with_limits',source_reviewed=['ANC-S05'],assessment='Frontinus §118 explicitly names treasury, water-right receipts and emperor’s purse; §§121–123 prescribe repair timing. Funding→designated workforce is bounded observed contribution. No audited service effect, adequate payment or voluntary employment follows. The two edges share one source, so the path supplies no independent corroboration.'),
'ANC-E11':dict(selection='Ordinary noncontroversial physical relation; necessity direction control.',verdict='supported_with_limits',source_reviewed=['ANC-S07'],assessment='Procopius Wars V.19.20–22 describes wheels between moored boats driven by current. depends-on points from boatmill to current, correctly. High physical confidence need not equal confidence in the narrative’s city-wide sufficiency. Removing current disables this configuration; different power substitutes change the configuration. No diffusion denominator claimed.'),
'IND-E01':dict(selection='Endpoint of cross-case shared-node path; technical possibility versus operation.',verdict='revise_node_identity',source_reviewed=[],assessment='The edge itself is scoped to central-European mine drainage and uses technical-possibility rather than claiming prevalence. IND-K01 is appropriately descriptive about Agricola; IND-K02 supports configuration change, not cost advantage. IND-T02 nevertheless shares identity with British textile waterpower in IND-C03. Scope text does not satisfy the v2 separate-local-nodes requirement.'),
'IND-E09':dict(selection='Other side of cross-case shared-node path and partial/abstract supporting claims.',verdict='revise_node_identity',source_reviewed=[],assessment='Competition at particular mill locations is narrower than a national hydropower comparison. IND-K07 is medium/underdetermined; IND-K08 is low/underdetermined abstract-only reservoir interpretation. Medium edge confidence does not alone imply the low-access mechanism is confirmed. The endpoint IND-T02 joins this British textile configuration to IND-E01 central-European mine pumping; split the node. No physical necessity or documented transmission is claimed.'),
'IND-E27':dict(selection='Explicit joint-input bundle and task-specific productivity attribution.',verdict='supported_with_limits',source_reviewed=[],assessment='IND-K24 proposes compatible machinery/redesign plus service as a pathway and gives demand/new-capital rivalry with matched-plant discrimination still missing. Medium observed-contribution and no necessity claim are reasonable as a historical interpretation. The counterpart joint input IND-T31 is real and in the same case. This bundle cannot establish that every motor installation needs complete redesign or a utility.'),
'IND-E28':dict(selection='Second member of joint bundle; utility service versus onsite alternative.',verdict='supported_with_limits',source_reviewed=[],assessment='The reciprocal joint-input reference to IND-T30 is consistent with IND-E27. Onsite generation is named as an alternative, and the claim is undetermined rather than identified. IND-C08 distinguishes horsepower from establishment/use shares; the graph cannot convert aggregate motor capacity into unit-drive uptake or worker welfare. No transitive or joint necessity is established.'),
'MAT-E06':dict(selection='Modern experimental necessity sharing a node with ancient deployment.',verdict='revise_node_identity',source_reviewed=[],assessment='The local counterfactual is sound: new iron by ore reduction requires iron-bearing feedstock, while imported metal bypasses the task. MAT-K12 openly acknowledges coupled parameter changes, so evaluated means feasibility evidence rather than isolated effects. MAT-T28 improperly combines ancient later/post-Meroitic process and modern replica; split identities despite the experimental scope text.'),
'MAT-E08':dict(selection='Ancient archaeological fuel contribution connected to experimental necessity through MAT-T28.',verdict='revise_node_identity',source_reviewed=[],assessment='MAT-K13 describes archaeological charcoal selection; observed-contribution with alternative taxa and unresolved provenance avoids a claim that acacia is uniquely necessary or sustainable. The ancient edge nevertheless targets a node naming both ancient operation and modern replicas. MAT-E08→MAT-E06 is therefore a cross-subepisode path that must not imply the ancient fuel record proves the replica’s input configuration or vice versa.'),
'LBR-E01':dict(selection='Weak-access organisational mechanism and alternative technical/scale explanations.',verdict='supported_as_attributed_interpretation',source_reviewed=['LBR-S01'],assessment='The author abstract explicitly states firm/technology adaptation and market-scale profitability. The edge flags author-summary support; LBR-K01 test is underdetermined and says full mechanism evidence was not acquired. observed-contribution is defensible only as an attributed historical interpretation, not an independently identified organisational effect. Full-text archival tests remain necessary before strengthening it.')
}
rows=[]
for eid,review in reviews.items():
    e=idx[eid]
    rows.append({'edge_id':eid,'location':structure['json_locations'][eid],'edge_record':e,'linked_claims':[{'id':k,'location':structure['json_locations'][k],'statement':idx[k]['statement'],'causal_status':idx[k]['causal_status'],'confidence':idx[k]['confidence'],'test':idx[k]['test'],'inference_limits':idx[k]['inference_limits']} for k in e['claim_ids']],'checks':{'basis_and_relation':'reviewed','scope_and_node_identity':'finding G01' if review['verdict']=='revise_node_identity' else 'reviewed','alternatives':'reviewed','joint_inputs':'reviewed','necessity':'reviewed','uncertainty_propagation':'reviewed','export':'fields preserved in controlled complete-dossier temporary-copy run'},**review})
claims=sorted({k for eid in reviews for k in idx[eid]['claim_ids']})
sources=sorted({k for eid in reviews for k in idx[eid]['source_ids']})
result={'date':'2026-11-05','input':'r1-snapshot only; external source passages checked for the three specified source records','sampling':'Purposive risk-based 10-edge sample: cross-episode node identity, ordinary physical necessity, coerced maintenance and finance, explicit joint-input bundle, experimental/ancient distinction, abstract-only mechanism. Not a random sample and not a prevalence estimate.','denominators':{'all_cases_structurally_checked':23,'all_claims_structurally_checked':78,'all_sources_lineage_screened':49,'all_edges_structurally_checked':72,'all_nodes_structurally_checked':93,'all_comparisons_screened':13,'detailed_edges':10,'distinct_linked_claims':len(claims),'distinct_linked_source_records':len(sources),'source_records_passage_checked':3,'sample_edges_with_source_passage_check':4},'sample_edge_ids':list(reviews),'linked_claim_ids':claims,'linked_source_ids':sources,'source_passage_checks':[
{'source_id':'ANC-S05','url':idx['ANC-S05']['url'],'passages':'De aquaeductu II §§116–118, 121–123; independently read web edition, with frozen local copy available.','supports_edge_ids':['ANC-E06','ANC-E07'],'result':'Pass for reported enslaved specialist workforce and named finance arrangements; not an operational audit or free-labour evidence.'},
{'source_id':'ANC-S07','url':idx['ANC-S07']['url'],'passages':'Wars V.19.13,19–28; independently read web edition.','supports_edge_ids':['ANC-E11'],'result':'Pass for described current-driven boatmill configuration; one narrative witness, no measured output or universal permanence claim.'},
{'source_id':'LBR-S01','url':'https://jamesfeigenbaum.github.io/research/att/','passages':'Author abstract, especially adaptation/interdependencies and market-size paragraph.','supports_edge_ids':['LBR-E01'],'result':'Pass for attributed author interpretation only. Full article and archive not independently checked.'}],
'path_reviews':[
{'edges':['ANC-E07','ANC-E06'],'result':'Same c.100 CE episode. Finance→workforce→service is intelligible but the path cannot identify a total causal effect or count as independent confirmation.'},
{'edges':['IND-E09','IND-E01'],'result':'Cross-case node identity conflates British textile and central-European mining waterpower. Typed competes-with/enables adjacency is not causal closure; split IND-T02.'},
{'edges':['MAT-E08','MAT-E06'],'result':'Same case but different ancient versus modern subepisodes. Shared MAT-T28 should be split; necessity direction also prevents reading this as a simple enabling chain.'},
{'edges':['IND-E27','IND-E28'],'result':'Common-target explicit joint bundle; paired incoming edges and counterpart lists neither prove joint necessity nor sufficient cause. Alternative onsite generation remains visible.'}],
'edges':rows,'limits':'No full MAT/IND source re-audit, no reconstruction of historical datasets, no running statistical models, no visual browser interaction. Record/claim reading and source-passage review are reported separately. No source material or live main collection was changed.'}
(out/'edge_audit.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'sample_edge_ids':list(reviews),'linked_claim_ids':claims,'linked_source_ids':sources,'denominators':result['denominators']},indent=2))
